package assignments_001_036;

public class Assignment_08 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
//		Write a program on Switch Case
		
		String a = "E";
		
		switch(a.toUpperCase()){
			
		case "A" :
			System.out.print(a+" is a Vowel");
			break;
			
		case "E" :
			System.out.print(a+" is a Vowel");
			break;
			
		case "I" :
			System.out.print(a+" is a Vowel");
			break;
			
		case "O" :
			System.out.print(a+" is a Vowel");
			break;
			
		case "U" :
			System.out.print(a+" is a Vowel");
			break;
			
		 default :
			System.out.print(a+" is a Constraint");
			break;
			
		}
	}

}
